function fqBytes64(text) {
    try { return Packages.java.util.Base64.getDecoder().decode(String(text)); }
    catch (ignore) { return Packages.android.util.Base64.decode(String(text),0); }
}
function fqEndpoint(name) {
    var item=FQ_ENDPOINT_DATA.origins[name];
    if(!item) throw new Error('番茄：地址配置无效');
    try {
        var cipher=Packages.javax.crypto.Cipher.getInstance('AES/GCM/NoPadding');
        var key=new Packages.javax.crypto.spec.SecretKeySpec(fqBytes64(FQ_ENDPOINT_DATA.key),'AES');
        var spec=new Packages.javax.crypto.spec.GCMParameterSpec(128,fqBytes64(item.iv));
        cipher.init(2,key,spec);
        return String(new Packages.java.lang.String(cipher.doFinal(fqBytes64(item.body)),'UTF-8'));
