function fqString(value) { return value == null ? '' : String(value); }
function fqId(value) {
    var id = fqString(value);
    if (!/^\d{1,22}$/.test(id)) throw new Error('番茄：无效的书籍或章节标识');
    return id;
}

/* Preserve opaque 64-bit IDs. Do not evaluate text supplied by a website. */
function fqParseJson(input, allowUndefined) {
    var text = fqString(input);
    // Most directory IDs already are strings. Keep the normal path in the native parser.
    if ((allowUndefined && /\bundefined\b/.test(text)) || /(?:^|[:,\[])\s*-?\d{16,}(?=\s*[,}\]]|\s*$)/.test(text)) {
        text = text.replace(/"(?:\\.|[^"\\])*"|\bundefined\b|-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?/g,
            function (token, offset, original) {
                if (token.charAt(0) === '"') return token;
                if (token === 'undefined') {
                    return allowUndefined && /[\s,:\[]/.test(offset ? original.charAt(offset - 1) : ' ') &&
                        /[\s,}\]]/.test(original.charAt(offset + token.length) || ' ') ? 'null' : token;
                }
                return /^-?\d{16,}$/.test(token) ? JSON.stringify(token) : token;
            });
    }
    try { return JSON.parse(text); }
    catch (e) { throw new Error('番茄：响应不是预期的 JSON；可能需要登录或网页验证'); }
}

function fqState(input) {
    var html = fqString(input), marker = /window\.__INITIAL_STATE__\s*=\s*/.exec(html);
    if (!marker) throw new Error('番茄：网页没有阅读数据，请打开官网核对登录或验证状态');
    var start = marker.index + marker[0].length, depth = 0, quoted = false, escaped = false;
    if (html.charAt(start) !== '{') throw new Error('番茄：网页数据格式已改变');
    for (var i = start; i < html.length; i++) {
        var c = html.charAt(i);
        if (quoted) {
            if (escaped) escaped = false;
            else if (c === '\\') escaped = true;
            else if (c === '"') quoted = false;
        } else if (c === '"') quoted = true;
        else if (c === '{') depth++;
        else if (c === '}' && --depth === 0) return fqParseJson(html.slice(start, i + 1), true);
    }
    throw new Error('番茄：网页数据不完整');
