    }
    if (!Array.isArray(items)) return fqString(items);
    var names = [];
    for (var i = 0; i < items.length; i++) {
        var name = fqString(items[i] && (items[i].Name || items[i].name));
        if (name && names.indexOf(name) < 0) names.push(name);
