    var rows = [], seen = {};
    for (var v = 0; v < volumes.length; v++) {
        if (!Array.isArray(volumes[v])) throw new Error('番茄：分卷结构已改变');
        for (var i = 0; i < volumes[v].length; i++) {
            var chapter = volumes[v][i], id = fqId(chapter.itemId);
            if (seen[id]) throw new Error('番茄：目录出现重复章节，请刷新目录');
            seen[id] = true;
            rows.push(chapter);
        }
    }
    if (!rows.length) throw new Error('番茄：目录为空');
    if (Array.isArray(data.allItemIds) && rows.length !== data.allItemIds.length) {
        throw new Error('番茄：目录数量不完整，请刷新目录');
    }
