        // Preserve the signed host, path and query. Only this scheme upgrade has
        // been checked against the official image; switching CDN hosts gives 403.
        url = url.replace(/^http:\/\/p3-reading-sign\.fqnovelpic\.com\//i, 'https://p3-reading-sign.fqnovelpic.com/');
        if (!/^https?:\/\//i.test(url) || /[\x00-\x20<>"'`]/.test(url) || url.indexOf(',{') >= 0) return missing();
        return '<img src="' + url.replace(/&/g, '&amp;') + '">';
    }
    return fqString(input).replace(/<img\b[^>]*>(?:\s*<\/img>)?/gi, function (tag) {
        var mapped = /\ssrc\s*=\s*(["'])\{\{image_domain\}\}(\{[\s\S]*\})\1/i.exec(tag);
        if (mapped) {
            try {
                var image = fqParseJson(mapped[2].replace(/&quot;/gi, '"').replace(/&amp;/gi, '&'), false), uri = fqString(image.web_uri);
                if (!uri || !/^[A-Za-z0-9_./-]+$/.test(uri) || /(^|\/)\.\.(\/|$)/.test(uri)) {
