function fqChapter(input, expectedUrl) {
    var html = fqString(input), data = fqState(html).reader;
    data = data && data.chapterData;
    if (!data || !data.itemId || !data.bookId) throw new Error('番茄：没有取得本章数据');
    fqId(data.itemId); fqId(data.bookId);
    var expected = /\/reader\/(\d+)/.exec(fqString(expectedUrl));
    if (expected && expected[1] !== String(data.itemId)) throw new Error('番茄：章节跳转不一致，已停止读取');
