    }catch(ignore){if(required)throw new Error('无法读取网页登录会话，请稍后检查登录状态');return false;}
    if(/[\r\n\x00]/.test(webText)||!fqAccountAuthSignature(webText)) {
        if(required)throw new Error('网页尚未提供登录会话，请完成网页登录后重试');
        return false;
