            if(fqAccountAuthSignature(fqAccountCookieText(cookieHost))!==fqAccountAuthSignature(before))throw new Error('恢复失败');
        }catch(restoreError){throw new Error('官网会话同步失败，原有记录未能恢复，请重新网页登录');}
