            // applyToWebView removes fixed-target WebView cookies before
            // writing that (now empty) jar, and flushes CookieManager.
            // Suppression also protects against older bridges and asynchronous
            // or failed browser cleanup. No unrelated domains are touched.
            fqAccountSuppressBrowserSync(src,true);
