            if(typeof cookieHost.applyToWebView==='function') {
                try {
                    cookieHost.applyToWebView(FQ_ACCOUNT_SITE,FQ_ACCOUNT_SITE);
                    cookieHost.captureFromWebView(FQ_ACCOUNT_SITE,FQ_ACCOUNT_SITE);
                    browserCleared=!fqAccountAuthSignature(fqAccountCookieText(cookieHost));
                }catch(ignore){}
