/* Native ExploreKind controls: no WebView is needed for classic discovery.
 * Source state is authoritative; InfoMap only transports the current control
 * event. Each event patches one key after reading the latest source variable. */
var FQ_CLASSIC_FIELDS = {
    view:{title:'📁 选择分组',label:'📁 选择分组'},
    libraryGender:{title:'⚧ 书库频道',label:'⚧ 性别'},
    rankGender:{title:'⚧ 排行频道',label:'⚧ 性别'},
    group:{title:'🎯 分类范围',label:'🎯 分类范围'},
    creationStatus:{title:'📅 更新状态',label:'📅 更新状态'},
    wordCount:{title:'📏 字数篇幅',label:'📏 字数篇幅'},
    sort:{title:'🔢 排序规则',label:'🔢 排序规则'},
    rankMold:{title:'🏆 榜单类型',label:'🏆 榜单类型'}
};
var FQ_CLASSIC_KEYWORD = '☃关键词:书名/作者🔖';

function fqClassicOptions(key) {
    var d=FQ_DISCOVERY_DATA;
    if (key==='view') return [{id:'rank',name:'📊 排行榜'},{id:'library',name:'📚 分类书库'}];
    if (key==='libraryGender' || key==='rankGender') return d.channels.filter(function(x){return key==='libraryGender' || x.id!==-1;}).map(function(x){return {id:x.id,name:x.id===1?'♂ 男频':x.id===0?'♀ 女频':'📚 全部'};});
    if (key==='group') return d.groups.map(function(x){return {id:x,name:x};});
    if (key==='rankMold') return d.rankings.types;
    return d.filters[key] || [];
}

function fqClassicState(src) {
    var raw=fqStoredSettings(src).classicDiscovery;
    if (!raw || typeof raw!=='object' || Array.isArray(raw)) raw={};
    var state={}, fallback={view:'rank',libraryGender:1,rankGender:1,group:FQ_DISCOVERY_DATA.groups[0],creationStatus:-1,wordCount:-1,sort:0,rankMold:2};
    for(var key in FQ_CLASSIC_FIELDS) if(Object.prototype.hasOwnProperty.call(FQ_CLASSIC_FIELDS,key)) {
        var options=fqClassicOptions(key), value=fallback[key];
        for(var i=0;i<options.length;i++) if(String(options[i].id)===String(raw[key])) {value=options[i].id;break;}
        state[key]=value;
    }
    state.group=fqClassicCompatibleGroup(state.libraryGender,state.group);
    state.filtersExpanded=raw.filtersExpanded===true;
    var requestedPage=Number(raw.page);
    state.page=isFinite(requestedPage)?Math.max(0,Math.floor(requestedPage)):0;
    return state;
}

function fqClassicCompatibleGroup(gender,group) {
    var d=FQ_DISCOVERY_DATA, channel=d.channels[0], i;
    for(i=0;i<d.channels.length;i++) if(d.channels[i].id===gender) channel=d.channels[i];
    function hasItems(name) {return d.categories.some(function(x){return x.group===name && channel.categoryIds.indexOf(x.id)>=0;});}
    if(hasItems(group)) return group;
    for(i=0;i<d.groups.length;i++) if(hasItems(d.groups[i])) return d.groups[i];
    return group;
}

function fqClassicItems(state) {
    var d=FQ_DISCOVERY_DATA;
    if(state.view==='rank') return state.rankGender===0?d.rankings.female:d.rankings.male;
    var channel=d.channels[0];
    for(var i=0;i<d.channels.length;i++) if(d.channels[i].id===state.libraryGender) channel=d.channels[i];
    return d.categories.filter(function(x){return x.group===state.group && channel.categoryIds.indexOf(x.id)>=0;});
}

function fqClassicPageInfo(state) {
    var items=fqClassicItems(state), size=24, count=Math.max(1,Math.ceil(items.length/size));
    return {items:items,size:size,count:count,page:Math.min(state.page,count-1)};
}

function fqClassicLabel(key,value) {
    var options=fqClassicOptions(key);
    for(var i=0;i<options.length;i++) if(options[i].id===value) return options[i].name;
    return '';
}

function fqClassicSyncForm(src,form,keys) {
    if(!form) return;
    var state=fqClassicState(src);
    for(var i=0;i<keys.length;i++) {
        var key=keys[i];
        var name=FQ_CLASSIC_FIELDS[key].title, value=fqClassicLabel(key,state[key]);
        try { if(typeof form.put==='function') form.put(name,value); else form[name]=value; } catch(ignore) {}
    }
}

function fqClassicRefresh(src,host,form) {
    try { if(src && typeof src.refreshExplore==='function') src.refreshExplore(); } catch(ignore) {}
    if(host && typeof host.refreshExplore==='function') {host.refreshExplore();return;}
    fqSettingsToast(host,'已保存，请返回发现页刷新');
}

function fqClassicPatch(src,host,form,patch,syncKeys) {
    var values=fqStoredSettings(src), current=values.classicDiscovery;
    if(!current || typeof current!=='object' || Array.isArray(current)) current={};
    for(var key in patch) if(Object.prototype.hasOwnProperty.call(patch,key)) current[key]=patch[key];
    values.classicDiscovery=current;
    src.putVariable(JSON.stringify(values));
    if(syncKeys && syncKeys.length) fqClassicSyncForm(src,form,syncKeys);
    // Commit native control state in the same user action. Reading a menu
    // still never writes the map and cannot overwrite a pending selection.
    if(form && typeof form.saveNow==='function') form.saveNow();
    fqClassicRefresh(src,host,form);
}

