    var raw=form && typeof form.get==='function'?form.get(name):form && form[name];
    var options=fqClassicOptions(key), found=false, value;
    for(var i=0;i<options.length;i++) if(options[i].name===fqString(raw)) {found=true;value=options[i].id;break;}
    if(!found) throw new Error('番茄：发现选项已变化，请刷新发现页');
