function fqReviewImage(value) {
    var url = fqString(value);
    return /^https:\/\/[^\s<>"']+$/.test(url) ? url : '';
}

function fqHttpJson(url, label, host) {
    var response = host.connect(url);
    var body;
    if (response != null && typeof response.code === 'function' && typeof response.body === 'function') {
        if (Number(response.code()) < 200 || Number(response.code()) >= 300) {
            throw new Error('番茄：' + label + ' HTTP ' + response.code());
        }
        body = fqString(response.body());
    } else {
        // Some standalone rule testers return text only. No HTTP status is inferred.
        body = fqString(response);
    }
    if (!body.trim()) throw new Error('番茄：' + label + '返回空响应，可能需要官网验证');
    return fqParseJson(body, false);
}

function fqRemovedReview() {
    throw new Error('番茄：本书书评和章末评论已移除，请刷新书籍详情与本章后使用段评');
}

