function fqSafeConfig(value) {
    return JSON.stringify(value).replace(/</g, '\\u003c').replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');
}

function fqShowReviews(config, host) {
    if (config && (config.kind === 'book' || config.kind === 'chapter')) fqRemovedReview();
    if (!config || config.kind !== 'paragraph') throw new Error('番茄：评论入口类型无效');
    config.theme=fqTheme(host);
    var html = FQ_REVIEW_HTML.replace('"__FQ_CONFIG__"', function () { return fqSafeConfig(config); });
    if (typeof host.showBrowser !== 'function') throw new Error('当前阅读版本未提供段评窗口接口，请更新此阅读分支后重试');
    host.showBrowser(FQ_ORIGIN + '/', html, 'window.fqRun = run;', null);
}

function fqOpenReviewPayload(encoded, host) {
    var config = fqParseJson(host.base64Decode(fqString(encoded)), false);
    if (config && config.kind === 'paragraph') {
        fqOpenParagraphReviews(config.bookId, config.chapterId, config.paragraph, config.version,
            config.quote, config.bookName, host, config.chapterTitle);
    } else if (config && (config.kind === 'book' || config.kind === 'chapter')) fqRemovedReview();
    else throw new Error('番茄：评论入口类型无效');
}

function fqChapterDiscussionEntry() { return ''; }

