    return fqReviewedChapter(fqChapter(input, expectedUrl),host,src,cacheHost);
}

function fqReviewedChapter(chapter, host, src, cacheHost) {
    fqRememberChapterWords(chapter, src, cacheHost);
    var stats = null, settings = fqSettings(src);
    try { if (settings.bubbleMode !== 'off') stats = fqCachedParagraphStats(chapter.bookId, chapter.itemId, host, src, cacheHost, settings); }
    catch (error) { /* Reading remains available; a click retries the real API and reports its error. */ }
    var rows = fqParagraphs(chapter.content), index = 0;
    var content = chapter.content.replace(/<p\b[^>]*>([\s\S]*?)<\/p>/gi, function (whole, inner) {
        var row = rows[index++];
        return '<p>' + inner + fqParagraphIcon(chapter, row, stats, host, settings) + '</p>';
    });
    return content;
}

