dary:'--muted',primary:'--primary',surface:'--surface',soft:'--soft',selectedBackground:'--selected',divider:'--line'};Object.keys(keys).forEach(function(k){if(theme[k])document.documentElement.style.setProperty(keys[k],theme[k]);});document.documentElement.style.setProperty('color-scheme',theme.dark?'dark':'light');}\n function theme(){try{if(typeof fqTheme==='function'&&typeof java!=='undefined')apply(fqTheme(java));}catch(ignore){}}\n apply(config.theme);theme();window.addEventListener('pageshow',theme);document.addEventListener('visibilitychange',function(){if(!document.hidden)theme();});\n [book.status,book.words,book.chapters?'共'+book.chapters+'章':'',book.readers].forEach(function(text){if(text){var item=document.createElement('span');item.textContent=text;el('summary').appendChild(item);}});\n el('summary').hidden=!el('summary').children.length;\n book.tags.forEach(function(text){var item=document.createElement('span');item.className='tag';item.textContent=text;el('tags').appendChild(item);});el('tags').hidden=!book.tags.length;\n el('updated').textContent=book.updated?'更新于 '+book.updated:'';el('updated').hidden=!book.updated;\n el('information').hidden=!el('summary').children.length&&!book.tags.length&&!book.updated;\n el('abstract').textContent=book.abstract||'暂无简介';\n})();\n</script></body></html>\n";

function fqInfoNumber(value, unit) {
    var n = Number(value);
    if (!isFinite(n) || n <= 0) return '';
    return (n >= 10000 ? (Math.round(n / 1000) / 10).toFixed(1).replace(/\.0$/, '') + '万' : String(Math.floor(n))) + unit;
}

function fqInfoDate(value) {
    var n = Number(value);
    if (!isFinite(n) || n <= 0) return '';
    // Platform timestamps are seconds. Display the site's China time independently
    // of the testing computer's local time zone.
    var d = new Date(n * 1000 + 8 * 3600000);
    if (isNaN(d.getTime())) return '';
    function pad(x) { return ('0' + x).slice(-2); }
    return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()) + ' ' + pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes());
}

function fqInfoModel(input, src, cacheHost) {
    var b = fqParseJson(input, false), tags = [], categories;
    try { categories = typeof b.categoryV2 === 'string' ? fqParseJson(b.categoryV2, false) : b.categoryV2; } catch (ignore) {}
    if (Array.isArray(categories)) for (var i = 0; i < categories.length; i++) {
        var name = fqString(categories[i] && (categories[i].Name || categories[i].name)).trim();
        if (name && tags.indexOf(name) < 0) tags.push(name);
    }
    if (!tags.length && b.category) tags = fqString(b.category).split(' · ');
    var status = String(b.creationStatus) === '0' ? '已完结' : String(b.creationStatus) === '1' ? '连载中' : '';
    return {bookId:fqId(b.bookId),bookName:fqString(b.bookName),status:status,chapters:fqCachedTocSize(b.bookId,src,cacheHost),
        words:fqInfoNumber(b.wordNumber, '字'),readers:fqInfoNumber(b.readCount, '人在读'),
        updated:fqInfoDate(b.lastPublishTime),tags:tags,abstract:fqString(b.abstract)};
}

function fqBookIntro(input, host, src, cacheHost) {
    var config = {book:fqInfoModel(input,src,cacheHost),theme:fqTheme(host)};
    // AnalyzeRule decodes HTML entities once before handing <useweb> to WebView.
    // Keep remote prose in JSON and escape ampersands as well as '<' so neither
    // this layer nor the browser can turn prose into executable markup.
    var encoded = fqSafeConfig(config).replace(/&/g, '\\u0026');
    return '<useweb>' + FQ_INTRO_HTML.replace('"__FQ_INTRO__"', function () { return encoded; }) + '</useweb>';
}

/* Official paragraph-share protocol; IDs are kept as strings throughout. */
function fqParagraphText(html) {
    var named = {amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' '};
    return fqString(html).replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]*>/g, '')
        .replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos|nbsp);/gi, function (all, code) {
            if (code.charAt(0) !== '#') return named[code.toLowerCase()];
            var n = code.charAt(1).toLowerCase() === 'x' ? parseInt(code.slice(2), 16) : parseInt(code.slice(1), 10);
            if (n < 0 || n > 1114111 || (n >= 55296 && n <= 57343)) return all;
            if (n <= 65535) return String.fromCharCode(n);
            n -= 65536; return String.fromCharCode(55296 + (n >> 10), 56320 + (n & 1023));
        }).trim();
}

function fqParagraphs(content) {
    var rows = [], expression = /<p\b[^>]*>([\s\S]*?)<\/p>/gi, match, remoteIndex = 0;
    while ((match = expression.exec(content)) !== null) {
        var text = fqParagraphText(match[1]);
        var identity = match[1].replace(/<\/?p\b[^>]*>/gi, '').trim();
        // XHTML chapter headings may themselves be wrapped in <p>. The official
        // paragraph endpoint counts body text, excluding this structural title.
        var heading = /^<h[1-6]\b[^>]*>[\s\S]*<\/h[1-6]\s*>$/i.test(identity);
        rows.push({index: rows.length, remoteIndex: text && !heading ? remoteIndex++ : null, html: match[1], text: text});
    }
    if (!rows.length) throw new Error('番茄：未能识别原始段落结构');
    return rows;
}

function fqOffset(value) {
    var n = Number(value);
    if (!isFinite(n) || n < 0 || Math.floor(n) !== n || n > 1000000) throw new Error('番茄：无效评论游标');
    return n;
}

function fqNormalizeParagraphComment(row, isReply) {
    var user = row.user_info || {}, pos = row.comment_pos || {};
    return {id: fqId(isReply ? row.reply_id : row.comment_id),
        name: fqString(user.user_name), content: fqString(row.text), avatar: fqReviewImage(user.user_avatar),
        authorBadge: user.is_author === true ? '作者' : '',
        likes: Number(row.digg_count) || 0, replies: Number(isReply ? row.reply_cnt : row.reply_count) || 0,
        time: Number(row.create_timestamp) || 0,
        paragraphStart: pos.start_para_index == null ? null : Number(pos.start_para_index),
        paragraphEnd: pos.end_para_index == null ? null : Number(pos.end_para_index),
        quote: fqString(row.para_src_content)};
}

function fqLoadParagraphStats(bookId, chapterId, host) {
    var json = fqHttpJson(fqEndpoint('comments')+'/reading/ugc/idea/list/v?aid=1967&book_id=' +
        fqId(bookId) + '&item_id=' + fqId(chapterId) + '&item_version=1', '段评统计', host);
    if (String(json.code) === '0' && json.data && json.data.idea_data === null) {
        return {counts: {}, version: fqString(json.data.newest_item_version) || '1', supported: false};
    }
    if (String(json.code) !== '0' || !json.data || !json.data.idea_data ||
        typeof json.data.idea_data !== 'object' || Array.isArray(json.data.idea_data)) {
        throw new Error('番茄：未取得段评统计');
    }
    var counts = {}, sourceCounts = json.data.idea_data;
    for (var key in sourceCounts) {
        if (Object.prototype.hasOwnProperty.call(sourceCounts, key) && /^\d+$/.test(key)) {
            var count = Number(sourceCounts[key].idea_count);
            if (isFinite(count) && count >= 0) counts[key] = count;
        }
    }
    return {counts: counts, version: fqString(json.data.newest_item_version) || '1', supported: true};
}

/* Compare the current paragraph with an exact, same-scope official anchor.
 * A stale hot-list quote is accepted only when current/old lists also share
 * a stable comment identity or observed paragraph hash. Never fuzzy-match text.
 */
function fqParagraphCheckRows(rows, bid, cid, index) {
    for (var i = 0; i < rows.length; i++) {
        var row = rows[i], pos = row && row.comment_pos || {};
        if (!row || String(row.book_id) !== bid || String(row.group_id) !== cid || Number(row.service_id) !== 1 ||
            pos.start_para_index == null || pos.end_para_index == null ||
            Number(pos.start_para_index) !== index || Number(pos.end_para_index) !== index) {
            throw new Error('番茄：评论不属于当前段落，已停止展示');
        }
        fqId(row.comment_id);
    }
}

function fqParagraphCheckQuotes(rows, currentQuote, historicQuote) {
    for (var i = 0; i < rows.length; i++) {
        var value = fqString(rows[i].para_src_content).trim();
        if (value && value !== currentQuote && (!historicQuote || value !== historicQuote)) {
            throw new Error('番茄：评论引用原文不一致，已停止展示');
        }
    }
}

function fqParagraphData(bid, cid, version, index, start, sort, host) {
    var url = fqEndpoint('comments')+'/reading/ugc/idea/comment_list/v?aid=1967&book_id=' + bid +
        '&item_id=' + cid + '&para_index=' + index + '&count=20&offset=' + start + '&query_type=0&sort=' + sort +
        '&item_version=' + encodeURIComponent(version);
    var json = fqHttpJson(url, '段评列表', host), data = json.data;
    if (String(json.code) !== '0' || !data) throw new Error('番茄：未取得本段评论列表');
    if (data.comments === null && data.has_more === false) data.comments = [];
    if (!Array.isArray(data.comments)) throw new Error('番茄：段评列表格式异常');
    fqParagraphCheckRows(data.comments, bid, cid, index);
    var more = data.has_more === true || data.has_more === 1, next = fqOffset(data.next_offset);
    if (data.next_page_type != null && Number(data.next_page_type) !== 0) {
        throw new Error('番茄：服务端切换了段评分页类型，当前书源暂不支持该后续页');
    }
    if (more && next <= start) throw new Error('番茄：段评游标没有推进');
    return data;
}

function fqParagraphAssociation(hot, current) {
    var ids = {}, hashes = {}, i, row, hash;
    for (i = 0; i < current.length; i++) {
        row = current[i]; ids['id:' + fqId(row.comment_id)] = true;
        hash = fqString(row.novel_para_hash_code).toLowerCase();
        // The captured protocol uses a 40-character hex string. Treat its
        // bytes as opaque: no guessed algorithm or recomputed hash is used.
        if (/^[0-9a-f]{40}$/.test(hash) && !/^0+$/.test(hash)) hashes[hash] = true;
    }
    for (i = 0; i < hot.length; i++) {
        row = hot[i];
        if (ids['id:' + fqId(row.comment_id)]) return {kind: 'comment', value: fqId(row.comment_id)};
    }
    for (i = 0; i < hot.length; i++) {
        hash = fqString(hot[i].novel_para_hash_code).toLowerCase();
        if (hash && hashes[hash]) return {kind: 'paragraphHash', value: hash};
    }
    return null;
}

function fqParagraphProofMatches(proof, bid, cid, version, index, currentQuote, historicQuote) {
    if (!proof || proof.schema !== 1 || proof.bookId !== bid || proof.chapterId !== cid ||
        proof.version !== version || proof.paragraph !== index || proof.currentQuote !== currentQuote ||
        proof.historicalQuote !== historicQuote || !proof.association) return false;
    var now = Date.now(), checked = Number(proof.checkedAt), expiry = Number(proof.expiresAt);
    if (!isFinite(checked) || !isFinite(expiry) || checked > now || expiry <= now ||
        expiry <= checked || expiry - checked > 300000) return false;
    var link = proof.association;
    return link.kind === 'comment' && /^\d+$/.test(fqString(link.value)) ||
        link.kind === 'paragraphHash' && /^[0-9a-f]{40}$/.test(fqString(link.value)) && !/^0+$/.test(link.value);
}

function fqLoadParagraphComments(bookId, chapterId, version, paragraph, quote, offset, sort, proof, host) {
    // Previous releases supplied the host directly after sort, or after offset.
    if (!host && proof && typeof proof.connect === 'function') { host = proof; proof = null; }
    if (!host && sort && typeof sort.connect === 'function') { host = sort; sort = 1; proof = null; }
    sort = Number(sort) === 3 ? 3 : 1;
    var bid = fqId(bookId), cid = fqId(chapterId), index = fqOffset(paragraph), start = fqOffset(offset);
    var requestedVersion = fqString(version) || '1';
    var data = fqParagraphData(bid, cid, requestedVersion, index, start, sort, host);
    var expectedQuote = fqString(quote).trim(), actualQuote = fqString(data.para_src_content).trim();
    var quoteStatus = actualQuote ? 'current' : 'unavailable', verifiedProof = null;
    if (actualQuote && actualQuote !== expectedQuote) {
        if (sort !== 1 || !expectedQuote) {
            throw new Error('番茄：段评引用原文与当前正文不一致，请刷新本章后重试');
        }
        if (fqParagraphProofMatches(proof, bid, cid, requestedVersion, index, expectedQuote, actualQuote)) {
            verifiedProof = proof;
        } else {
            // One bounded read only on the mismatch path; this verifies the
            // paragraph identity and never replaces the requested hot list.
            var current = fqParagraphData(bid, cid, requestedVersion, index, 0, 3, host);
            var currentQuote = fqString(current.para_src_content).trim();
            if (!current.comments.length || currentQuote !== expectedQuote) {
                throw new Error('番茄：热门评论保留了不同原文，暂无法确认与当前段落对应；可切换最新查看');
            }
            fqParagraphCheckQuotes(current.comments, expectedQuote, '');
            var association = fqParagraphAssociation(data.comments, current.comments);
            if (!association) {
                throw new Error('番茄：热门评论与当前段落缺少可核对的关联，已停止展示；可切换最新查看');
            }
            var checkedAt = Date.now();
            verifiedProof = {schema: 1, bookId: bid, chapterId: cid, version: requestedVersion,
                paragraph: index, currentQuote: expectedQuote, historicalQuote: actualQuote,
                association: association, checkedAt: checkedAt, expiresAt: checkedAt + 300000};
        }
        quoteStatus = 'historical';
    }
    // Preserve v8's established current-page contract. Some optional row
    // quote fields may describe selections or older comments; the captured
    // normal lists do not contain that field, so do not invent a new blocker.
    // The new historical path is stricter because it is granting an exception.
    if (!actualQuote || quoteStatus === 'historical') {
        fqParagraphCheckQuotes(data.comments, expectedQuote, quoteStatus === 'historical' ? actualQuote : '');
    }
    var items = [];
    for (var i = 0; i < data.comments.length; i++) items.push(fqNormalizeParagraphComment(data.comments[i], false));
    return {kind: 'paragraph', items: items, hasMore: data.has_more === true || data.has_more === 1,
        nextOffset: fqOffset(data.next_offset), total: data.count == null ? null : Number(data.count),
        quote: expectedQuote, quoteStatus: quoteStatus,
        historicalQuote: quoteStatus === 'historical' ? actualQuote : '',
        notice: quoteStatus === 'historical' ? '热门评论的引用原文与当前正文不同，已核对段落关联。' : '',
        paragraphProof: verifiedProof};
}


function fqOpenParagraphReviews(bookId, chapterId, paragraph, version, quote, bookName, host, chapterTitle) {
    fqShowReviews({kind: 'paragraph', bookId: fqId(bookId), chapterId: fqId(chapterId),
        paragraph: fqOffset(paragraph), version: fqString(version), quote: fqString(quote), bookName: fqString(bookName),chapterTitle:fqString(chapterTitle)}, host);
}

function fqParagraphIcon(chapter, row, stats, host, settings) {
    settings = settings || {bubbleMode: 'outline', showEmpty: false};
    // This renderer can be called by old saved scripts as well as fqSettings.
    // Only emit the shared data-SVG + TEXT + click protocol on every branch.
    var mode = settings.bubbleMode === 'max' ? 'outline' : settings.bubbleMode;
    if (row.remoteIndex == null || settings.bubbleMode === 'off' || (stats && stats.supported === false)) return '';
    var count = stats && stats.counts[String(row.remoteIndex)];
    if (stats && count == null) count = 0;
    if (count === 0 && !settings.showEmpty) return '';
    var label = count == null ? '评' : String(count), width = Math.max(24, 12 + label.length * 8);
    var svg;
    var payload = host.base64Encode(JSON.stringify({kind: 'paragraph', bookId: String(chapter.bookId),
        chapterId: String(chapter.itemId), paragraph: row.remoteIndex, version: stats ? stats.version : '1',
        quote: row.text, bookName: fqString(chapter.bookName),chapterTitle:fqString(chapter.title)}));
    var click = 'fqOpenReviewPayload(' + JSON.stringify(String(payload)) + ',java)';
    if (mode !== 'number') {
        svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + width + '" height="20" viewBox="0 0 ' + width + ' 20">' +
            '<path d="M4 2H' + (width - 4) + 'Q' + (width - 1) + ' 2 ' + (width - 1) + ' 5V13Q' + (width - 1) + ' 16 ' + (width - 4) + ' 16H9L5 19V16H4Q1 16 1 13V5Q1 2 4 2Z" fill="none" stroke="#999"/>' +
            '<text x="' + (width / 2) + '" y="12" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#888">' + label + '</text></svg>';
    } else {
        svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + width + '" height="18"><text x="' + (width / 2) + '" y="13" text-anchor="middle" font-size="11" fill="#888">' + label + '</text></svg>';
    }
    // Reading's imgPattern explicitly accepts raw option JSON inside src.
    // HTML-entity encoding this JSON breaks Beta's Gson option parser.
    return '<img src="data:image/svg+xml;base64,' + host.base64Encode(svg) + ',' + JSON.stringify({style: 'TEXT', click: click}) + '">';
}

function fqLoadParagraphTopic(bookId, chapterId, commentId, offset, host) {
    var bid = fqId(bookId), cid = fqId(chapterId), rid = fqId(commentId), start = fqOffset(offset);
    var json = fqHttpJson(fqEndpoint('comments')+'/reading/ugc/reply/topic/v?aid=1967&book_id=' + bid +
        '&comment_id=' + rid + '&service_id=1&group_id=' + cid + '&count=20&offset=' + start, '段评回复', host);
    var data = json.data;
    if (String(json.code) !== '0' || !data || !data.comment || !Array.isArray(data.reply_list)) {
        throw new Error('番茄：未取得段评详情或回复');
    }
    if (String(data.comment.comment_id) !== rid || String(data.comment.group_id) !== cid ||
        String(data.comment.book_id) !== bid || Number(data.comment.service_id) !== 1) {
        throw new Error('番茄：段评归属不一致，已停止展示');
    }
    var items = [];
    for (var i = 0; i < data.reply_list.length; i++) {
        var row = data.reply_list[i];
        if (String(row.reply_to_comment_id) !== rid) throw new Error('番茄：回复归属不一致');
        items.push(fqNormalizeParagraphComment(row, true));
    }
    var hasMore = data.has_more === true || data.has_more === 1, next = fqOffset(data.next_offset);
    if (hasMore && next <= start) throw new Error('番茄：回复游标没有推进');
    return {comment: fqNormalizeParagraphComment(data.comment, false), items: items,
        hasMore: hasMore, nextOffset: next, total: Number(data.count) || 0};
}

