source.searchUrl:
@js:
var html = java.ajax("https://rentry.la/agefans");

/*获取最新地址*/
var soUrl = org.jsoup.Jsoup.parse(html).select('#nice').select('#nice').select("blockquote")[0].select("p a")[0].html()

var re = /^(?:http(s)?:\/\/)?[\w.-]+(?:\.[\w\.-]+)+[\w\-\._~:/?#[\]@!\$&'\(\)\*\+,;=.]+$/

var su=source.getKey()

/*判断请求地址*/
var postUrl= soUrl && soUrl!="" && re.test(soUrl)?`${soUrl}/search`:su

// 获取最新的地址
var ajaxUrl = soUrl && soUrl!="" && re.test(soUrl)?soUrl:"https://www.agedm.org"

java.put("ajaxUrl",ajaxUrl)

postUrl+"?query={{key}}&page={{page}},"+JSON.stringify({
"webview":true
})

