bookInfoRule.intro:
@js:
u='■';nu='□';
var x = book.getVariable("custom")
if(!x || x==''){
x = 0
}
list = Array.from(java.getElements(".nav-tabs@li")).map((n,i)=>{
   return `${Number(i)==Number(x)?u:nu}节点：${n.text()}，书籍变量：${i},总集数：${java.getElements(`.myui-content__list[${Number(i)}]@li@a`).length}`
})
result = "   设置书籍变量，可以切换播放节点<br>"+list.join("<br>")+java.getString(".fed-drop-boxs@html")

contentRule.content:
@js:

var nowUrl =((src.match(/var now+( = |=)+("(.+)"|'(.+)')/)||[])[2]||'').replace(/"|'/g,'').split(";")[0]

var playIurl="https://www.dj5.org/js/player/dmplayer/player/index.php?url="+nowUrl

if(playIurl){
	if(book.durChapterIndex==chapter.index){
       java.toast(`播放地址：${String(playIurl)}`)
	      java.startBrowser(playIurl,title)

	      java.toast(title+":视频加载中，请等待…")

	}
}
result=`\n【刷新正文】播放\n<br>或者【点击章节链接】跳转到浏览器播放\n`
result;

