{{
var su=source.getKey()
su=su.includes("#")?su.match(/([^\#]+)\#/)[1]:su
var contentData=java.connect(su)

var posturl=String(contentData.raw().request().url())
posturl = posturl.slice(-1)=='/'?posturl.slice(0,-1):posturl

sc = org.jsoup.Jsoup.parse(contentData.body()).select('form[name=search]').attr('action');;
java.log(`请求：${posturl}`)
cookie.removeCookie(posturl);
posturl+sc
}}?searchword={{key}}

